) values (
  'c939601e-eec7-54be-ae56-9744cb0cbde9'::uuid, null, 'Timeless Wisdom', 'commander', 'Timeless Wisdom is an official Commander precon from C20, released 2020-04-17.', 'public', true, true,
  '80bc07d5-bdbb-4a6d-8958-0c172ea80245', 'Gavi, Nest Warden', 'Legendary Creature — Human Shaman', '{2}{U}{R}{W}',
  'https://cards.scryfall.io/normal/front/8/0/80bc07d5-bdbb-4a6d-8958-0c172ea80245.jpg', 'https://cards.scryfall.io/art_crop/front/8/0/80bc07d5-bdbb-4a6d-8958-0c172ea80245.jpg', ARRAY['W', 'U', 'R']::text[], ARRAY['W', 'U', 'R']::text[]
) on conflict (id) do update set
