  commander_image_uri, commander_art_uri, commander_color_identity, colors
) values (
  '19ce7f39-1116-5992-9b32-f5ea4bd1d340'::uuid, null, 'Reap the Tides', 'commander', 'Reap the Tides is an official Commander precon from CMR, released 2020-11-20.', 'public', true, true,
