insert into public.decks (
  id, owner_id, name, format, notes, visibility, allow_forks, is_precon,
  commander_scryfall_id, commander_name, commander_type_line, commander_mana_cost,
  commander_image_uri, commander_art_uri, commander_color_identity, colors
) values (
  '513812c5-1a80-589c-8506-76215a5aae7c'::uuid, null, 'Silverquill Statement', 'commander', 'Silverquill Statement is an official Commander precon from C21, released 2021-04-23.', 'public', true, true,
  '6cb82b10-d785-4e20-84ac-0660d49be8ad', 'Breena, the Demagogue', 'Legendary Creature — Bird Warlock', '{1}{W}{B}',
  'https://cards.scryfall.io/normal/front/6/c/6cb82b10-d785-4e20-84ac-0660d49be8ad.jpg', 'https://cards.scryfall.io/art_crop/front/6/c/6cb82b10-d785-4e20-84ac-0660d49be8ad.jpg', ARRAY['W', 'B']::text[], ARRAY['W', 'B']::text[]
) on conflict (id) do update set
  owner_id = excluded.owner_id,
  name = excluded.name,
  format = excluded.format,
  notes = excluded.notes,
  visibility = excluded.visibility,
