select v.deck_id, v.scryfall_id, v.card_name, v.image_uri, v.mana_cost, v.type_line, v.colors,
  v.color_identity, v.oracle_text, v.quantity, v.board
from (values
  ('d3762f91-8a1f-51e5-820f-ef134aaac0c8'::uuid, '0c7ce363-3f57-49ed-b89a-f12bb5227ab4', 'Anger', 'https://cards.scryfall.io/normal/front/0/c/0c7ce363-3f57-49ed-b89a-f12bb5227ab4.jpg', '{3}{R}', 'Creature — Incarnation', ARRAY['R']::text[], ARRAY['R']::text[], 'Haste
