) values (
  'b2fd8ad5-46f5-5b9c-8cf1-38fb62a97eae'::uuid, null, 'Spirit Squadron', 'commander', 'Spirit Squadron is an official Commander precon from VOC, released 2021-11-19.', 'public', true, true,
